#!/bin/bash
# macOS only: compile + exercise the sandbox-exec profiles generated by lib/task-runners.js (Studio4 M-2).
# Usage (on the Mac, in the repo): bash scripts/mac-sandbox-check.sh   -> prints PASS/FAIL lines, exit 1 on any FAIL.
set -u; cd "$(dirname "$0")/.."
[ "$(uname)" = Darwin ] || { echo "BLOCKED: macOS only"; exit 2; }
W=$(mktemp -d /tmp/mk-sbx-check.XXXX); W=$(cd "$W" && pwd -P); P="$HOME/.mk-sbx-planted-$$"; echo PLANTED > "$P"; F=0
ok() { if [ "$2" = 1 ]; then echo "PASS $1"; else echo "FAIL $1"; F=1; fi; }
prof() { node -e "const T=require('./lib/task-runners.js');const s=T.sandboxed(process.argv[1],[],{workDir:process.argv[2]});if(!s){console.error('no sandbox');process.exit(3)}process.stdout.write(s.profile)" "$1" "$W"; }
# 1. profile compiles and the binary runs (bash used as the probe binary: exec literal is /bin/bash)
PB=$(prof /bin/bash) || { echo "FAIL profile generation"; exit 1; }
sandbox-exec -p "$PB" /bin/bash -c 'exit 0' 2>"$W/err"; ok "profile compiles + exec of the allowed binary" $([ $? = 0 ] && echo 1 || echo 0); cat "$W/err"
# 2. real HOME not readable
sandbox-exec -p "$PB" /bin/bash -c "echo \"\$(<'$P')\"" >"$W/o" 2>/dev/null; ok "planted file in \$HOME not readable" $(grep -q PLANTED "$W/o" && echo 0 || echo 1)
# 3. no network to localhost (python http server or nc must not receive)
( sandbox-exec -p "$PB" /bin/bash -c 'exec 3<>/dev/tcp/127.0.0.1/22' ) 2>/dev/null; ok "no network (tcp connect refused by sandbox)" $([ $? != 0 ] && echo 1 || echo 0)
# 4. write in workDir works, outside does not
sandbox-exec -p "$PB" /bin/bash -c "echo x > '$W/in.txt'; echo y > /tmp/mk-sbx-out-$$.txt" 2>/dev/null
ok "write inside workDir" $([ -f "$W/in.txt" ] && echo 1 || echo 0); ok "no write outside workDir" $([ -f /tmp/mk-sbx-out-$$.txt ] && echo 0 || echo 1)
# 5. exec of a non-listed binary denied
sandbox-exec -p "$PB" /bin/bash -c '/usr/bin/curl --version' >/dev/null 2>&1; ok "exec of non-listed binary (curl) denied" $([ $? != 0 ] && echo 1 || echo 0)
# 6. ffmpeg (if installed) renders inside its own profile
if FF=$(command -v ffmpeg); then PF=$(prof "$FF"); sandbox-exec -p "$PF" "$FF" -hide_banner -loglevel error -f lavfi -i color=c=black:s=64x64:d=1 -t 1 "$W/t.mp4" 2>"$W/ff.err"
  ok "ffmpeg renders inside sandbox" $([ -s "$W/t.mp4" ] && echo 1 || echo 0); cat "$W/ff.err"; else echo "SKIP ffmpeg not installed"; fi
# 7. kill-tree incl. setsid-escaped grandchild
node -e "
const T=require('./lib/task-runners.js'),fs=require('fs');const f='$W/g.txt',s='$W/k.sh';
fs.writeFileSync(s,'#!/bin/bash\nperl -e \'use POSIX; setsid(); while(1){open F,\">>$W/g.txt\";print F 1;close F;select(undef,undef,undef,0.2)}\' &\nsleep 60\n',{mode:0o755});
const ac=new AbortController();const p=T.run(s,[],{cwd:'$W',signal:ac.signal}).catch(e=>e);
setTimeout(async()=>{ac.abort();await p;setTimeout(()=>{const a=fs.readFileSync(f).length;setTimeout(()=>{process.exit(a>0&&a===fs.readFileSync(f).length?0:1)},1200)},600)},800);"
ok "cancel kills setsid-escaped grandchild (ps walk)" $([ $? = 0 ] && echo 1 || echo 0)
rm -rf "$W" "$P" /tmp/mk-sbx-out-$$.txt; exit $F
